+package middleware
+
+import (
+	"context"
+	"testing"
+
+	"github.com/aws/aws-lambda-go/events"
+	"github.com/sitoo/go-utils-lambda/v2/alb/router"
+	"github.com/stretchr/testify/require"
+)
+
+func TestForwardedAuthorizationToCtx_StoresBasicHeader(t *testing.T) {
+	mw := ForwardedAuthorizationToCtx
+	called := false
+	next := func(ctx context.Context, req *events.ALBTargetGroupRequest) (*events.ALBTargetGroupResponse, error) {
+		called = true
+		got, ok := ForwardedAuthorizationFromCtx(ctx)
+		require.True(t, ok)
+		require.Equal(t, "Basic dXNlcjpwYXNz", got)
+		return &events.ALBTargetGroupResponse{StatusCode: 204}, nil
+	}
+	req := &events.ALBTargetGroupRequest{
+		Headers: map[string]string{"authorization": "Basic dXNlcjpwYXNz"},
+	}
+	ctx := router.WithRequestInfo(context.Background(), &router.RequestInfo{HasMultiValueHeaders: false})
+	_, err := mw(next)(ctx, req)
+	require.NoError(t, err)
+	require.True(t, called)
+}
+
+func TestForwardedAuthorizationToCtx_StoresBearerHeader(t *testing.T) {
+	mw := ForwardedAuthorizationToCtx
+	called := false
+	next := func(ctx context.Context, req *events.ALBTargetGroupRequest) (*events.ALBTargetGroupResponse, error) {
+		called = true
+		got, ok := ForwardedAuthorizationFromCtx(ctx)
+		require.True(t, ok)
+		require.Equal(t, "Bearer abc", got)
+		return &events.ALBTargetGroupResponse{StatusCode: 204}, nil
+	}
+	req := &events.ALBTargetGroupRequest{
+		Headers: map[string]string{"authorization": "Bearer abc"},
+	}
+	ctx := router.WithRequestInfo(context.Background(), &router.RequestInfo{HasMultiValueHeaders: false})
+	_, err := mw(next)(ctx, req)
+	require.NoError(t, err)
+	require.True(t, called)
+}
+
+func TestForwardedAuthorizationFromCtx_MissingReturnsFalse(t *testing.T) {
+	_, ok := ForwardedAuthorizationFromCtx(context.Background())
+	require.False(t, ok)
+}
+
+func TestForwardedAuthorizationToCtx_HeaderNameCaseInsensitive(t *testing.T) {
+	stored := false
+	next := func(ctx context.Context, req *events.ALBTargetGroupRequest) (*events.ALBTargetGroupResponse, error) {
+		_, stored = ForwardedAuthorizationFromCtx(ctx)
+		return &events.ALBTargetGroupResponse{StatusCode: 204}, nil
+	}
+	req := &events.ALBTargetGroupRequest{
+		Headers: map[string]string{"Authorization": "Basic dXNlcjpwYXNz"},
+	}
+	ctx := router.WithRequestInfo(context.Background(), &router.RequestInfo{HasMultiValueHeaders: false})
+	_, err := ForwardedAuthorizationToCtx(next)(ctx, req)
+	require.NoError(t, err)
+	require.True(t, stored)
+}
+
+func TestForwardedAuthorizationToCtx_MultiValueHeaders(t *testing.T) {
+	stored := false
+	next := func(ctx context.Context, req *events.ALBTargetGroupRequest) (*events.ALBTargetGroupResponse, error) {
+		_, stored = ForwardedAuthorizationFromCtx(ctx)
+		return &events.ALBTargetGroupResponse{StatusCode: 204}, nil
+	}
+	req := &events.ALBTargetGroupRequest{
+		MultiValueHeaders: map[string][]string{"Authorization": {"Basic dXNlcjpwYXNz"}},
+	}
+	ctx := router.WithRequestInfo(context.Background(), &router.RequestInfo{HasMultiValueHeaders: true})
+	_, err := ForwardedAuthorizationToCtx(next)(ctx, req)
+	require.NoError(t, err)
+	require.True(t, stored)
+}

