+package iam
+
+import (
+	"bytes"
+	"context"
+	"encoding/json"
+	"io"
+	"net/http"
+	"net/url"
+	"strconv"
+
+	"github.com/sitoo/go-utils-common/errors"
+)
+
+// HTTPClient implements Client against a running IAM API.
+type HTTPClient struct {
+	baseURL string // e.g. "https://iam.sitooapis.com/v1"
+	hc      *http.Client
+}
+
+func NewHTTPClient(baseURL string, hc *http.Client) *HTTPClient {
+	if hc == nil {
+		hc = http.DefaultClient
+	}
+	return &HTTPClient{baseURL: baseURL, hc: hc}
+}
+
+type listUserAssignmentsResponse struct {
+	Items []struct {
+		UserID      string           `json:"user_id"`
+		Assignments []wireAssignment `json:"assignments"`
+	} `json:"items"`
+}
+
+type wireAssignment struct {
+	Source       string  `json:"source"`
+	AssignmentID string  `json:"assignment_id"`
+	UserID       string  `json:"user_id"`
+	Environment  string  `json:"environment"`
+	AccountIDs   []int64 `json:"account_ids"`
+	SiteIDs      []int64 `json:"site_ids"`
+	StoreIDs     []int64 `json:"store_ids"`
+	RoleSlug     string  `json:"role_slug"`
+}
+
+func (w wireAssignment) toAssignment() Assignment {
+	return Assignment{
+		Source:       Source(w.Source),
+		AssignmentID: w.AssignmentID,
+		UserID:       w.UserID,
+		Environment:  Environment(w.Environment),
+		AccountIDs:   w.AccountIDs,
+		SiteIDs:      w.SiteIDs,
+		StoreIDs:     w.StoreIDs,
+		RoleSlug:     w.RoleSlug,
+	}
+}
+
+func (c *HTTPClient) ListUserAssignments(
+	ctx context.Context,
+	auth string,
+	in ListUserAssignmentsInput,
+) ([]Assignment, error) {
+	q := url.Values{}
+	for _, u := range in.UserIDs {
+		q.Add("user_ids[]", u)
+	}
+	q.Set("environment", string(in.Environment))
+	if in.AccountID != nil {
+		q.Set("account_id", strconv.FormatInt(*in.AccountID, 10))
+	}
+	if in.SiteID != nil {
+		q.Set("site_id", strconv.FormatInt(*in.SiteID, 10))
+	}
+	if in.StoreID != nil {
+		q.Set("store_id", strconv.FormatInt(*in.StoreID, 10))
+	}
+
+	resp, err := c.do(ctx, http.MethodGet, "/user-role-assignments?"+q.Encode(), auth, nil)
+	if err != nil {
+		return nil, err
+	}
+	defer func() { _ = resp.Body.Close() }()
+
+	if err := checkStatus(resp); err != nil {
+		return nil, err
+	}
+
+	var body listUserAssignmentsResponse
+	if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError, "iam response decode failed")
+	}
+	out := make([]Assignment, 0)
+	for _, group := range body.Items {
+		for _, a := range group.Assignments {
+			out = append(out, a.toAssignment())
+		}
+	}
+	return out, nil
+}
+
+type upsertAssignmentBySlugBody struct {
+	UserID      string  `json:"user_id"`
+	Environment string  `json:"environment,omitempty"`
+	AccountID   int64   `json:"account_id"`
+	SiteID      int64   `json:"site_id"`
+	StoreIDs    []int64 `json:"store_ids,omitempty"`
+	RoleSlug    string  `json:"role_slug,omitempty"`
+}
+
+type upsertAssignmentBySlugResponse struct {
+	Assignments []wireAssignment `json:"assignments"`
+}
+
+func (c *HTTPClient) UpsertAssignmentBySlug(
+	ctx context.Context,
+	auth string,
+	in UpsertAssignmentBySlugInput,
+) ([]Assignment, error) {
+	body := upsertAssignmentBySlugBody{
+		UserID:      in.UserID,
+		Environment: string(in.Environment),
+		AccountID:   in.AccountID,
+		SiteID:      in.SiteID,
+		StoreIDs:    in.StoreIDs,
+		RoleSlug:    in.RoleSlug,
+	}
+	raw, err := json.Marshal(body)
+	if err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError,
+			"iam request marshal failed")
+	}
+	resp, err := c.do(ctx, http.MethodPut, "/role-assignment-by-slug", auth, bytes.NewReader(raw))
+	if err != nil {
+		return nil, err
+	}
+	defer func() { _ = resp.Body.Close() }()
+	if err := checkStatus(resp); err != nil {
+		return nil, err
+	}
+	if resp.StatusCode == http.StatusNoContent {
+		return nil, nil
+	}
+	var decoded upsertAssignmentBySlugResponse
+	if err := json.NewDecoder(resp.Body).Decode(&decoded); err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError,
+			"iam response decode failed")
+	}
+	out := make([]Assignment, 0, len(decoded.Assignments))
+	for _, w := range decoded.Assignments {
+		out = append(out, w.toAssignment())
+	}
+	return out, nil
+}
+
+func (c *HTTPClient) do(
+	ctx context.Context,
+	method, path, auth string,
+	body io.Reader,
+) (*http.Response, error) {
+	req, err := http.NewRequestWithContext(ctx, method, c.baseURL+path, body)
+	if err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError, "iam request failed")
+	}
+	req.Header.Set("Authorization", auth)
+	if body != nil {
+		req.Header.Set("Content-Type", "application/json")
+	}
+	resp, err := c.hc.Do(req)
+	if err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError, "iam request failed")
+	}
+	return resp, nil
+}
+
+func checkStatus(resp *http.Response) error {
+	if resp.StatusCode >= 200 && resp.StatusCode < 300 {
+		return nil
+	}
+	raw, _ := io.ReadAll(resp.Body)
+	code := errors.CodeInternalServerError
+	switch resp.StatusCode {
+	case http.StatusUnauthorized:
+		code = errors.CodeUnauthorized
+	case http.StatusForbidden:
+		code = errors.CodeForbidden
+	case http.StatusNotFound:
+		code = errors.CodeNotFound
+	case http.StatusConflict:
+		code = errors.CodeConflict
+	default:
+		if resp.StatusCode >= 400 && resp.StatusCode < 500 {
+			code = errors.CodeInvalidInput
+		}
+	}
+	return errors.Errorf(code, "iam status %d: %s", resp.StatusCode, string(raw))
+}

