+package mysql
+
+import (
+	"bytes"
+	"context"
+	"database/sql"
+	"encoding/json"
+	"fmt"
+	"sort"
+	"strconv"
+	"strings"
+	"time"
+
+	"github.com/sitoo/auth/model"
+	"github.com/sitoo/go-utils-common/errors"
+	"github.com/sitoo/go-utils-common/guid"
+	"github.com/sitoo/go-utils-common/log"
+	"github.com/sitoo/go-utils-common/ptrtype"
+)
+
+// CreateUserV2 inserts a SCIM user row + identity claims + warehouse
+// privs. Role priv inserts are SKIPPED — IAM owns role for V2.
+func CreateUserV2(
+	c context.Context,
+	db *sql.DB,
+	siteID int64,
+	user *model.User,
+) (*model.User, error) {
+	if user.GetEmail() == "" {
+		return nil, errors.New(errors.CodeInternalServerError, "email must be specified")
+	}
+	if user.UserName == nil {
+		user.UserName = ptrtype.NewString("")
+	}
+
+	siteIDData, err := getSiteIDData(c, db, siteID)
+	if err != nil {
+		return nil, err
+	}
+
+	now := timeNow().UTC()
+	dateTimeNow := now.Format(dateTimeFmt)
+
+	// collect all user privileges
+	privs := []int{}
+	if user.IsPosRefundCard() {
+		privs = append(privs, userPrivPosRefundCard)
+	}
+	if user.IsPosAllStores() {
+		privs = append(privs, userPrivPosAllStores)
+	}
+	if !user.IsActive() {
+		privs = append(privs, userPrivNotActive)
+	}
+
+	ctx, cancelFn := context.WithTimeout(c, 15*time.Second)
+	defer cancelFn()
+
+	// make sure we don't have any duplicates
+	storeIDs := filterStrDuplicates(user.GetStores())
+	user.Stores = storeIDs
+
+	// add privileges for all warehouses on site. Stores are always written
+	// even when SkipRolePrivs is set, so the legacy DB always tracks the
+	// current store assignment regardless of bucket.
+	warehouseIDs, err := getStoresWarehouseIDs(ctx, db, storeIDs)
+	if err != nil {
+		return nil, err
+	}
+
+	for _, warehouseID := range warehouseIDs {
+		// warehouse priv have valid range between 10_000 to 60_000
+		priv := 10_000 + warehouseID
+		if priv > 60_000 {
+			return nil, errors.New(errors.CodeInternalServerError,
+				"could not create warehouse priv, warehouseID must be <= 60000")
+		}
+		privs = append(privs, priv)
+	}
+
+	tx, err := db.BeginTx(ctx, nil)
+	if err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError,
+			"could not create mysql transaction")
+	}
+
+	// Lookup user and what site the user have access to
+	userExistQuery := `
+		SELECT U.userid, P.siteid, U.jsondata
+		FROM sd_admin_users U
+		LEFT JOIN sd_admin_users_privs P ON U.userid = P.userid
+		WHERE U.email = ?
+		GROUP BY U.userid, P.siteid
+	`
+
+	rows, err := tx.QueryContext(ctx, userExistQuery, user.Email)
+	if err != nil {
+		rollback(ctx, tx, err, "failed rollback after user exist query")
+		return nil, errors.Wrap(err, errors.CodeInternalServerError,
+			"failed user exist query")
+	}
+
+	var userIDRaw []byte
+	userJsonData := make(map[string]any)
+
+	emailExist := false
+	for rows.Next() {
+		emailExist = true
+
+		var idData []byte
+		var existingSiteIDData []byte
+		var userJsonDataRaw *string
+		if err := rows.Scan(&idData, &existingSiteIDData, &userJsonDataRaw); err != nil {
+			_ = rows.Close()
+			rollback(ctx, tx, err, "failed rollback after user exist row scan")
+			return nil, errors.Wrap(err, errors.CodeInternalServerError,
+				"user exist result scan failed")
+		}
+
+		if bytes.Equal(existingSiteIDData, siteIDData) {
+			if err = rows.Close(); err != nil {
+				rollback(ctx, tx, err, "failed rollback after user exist row close")
+				return nil, errors.Wrap(err, errors.CodeInternalServerError,
+					"user exist result scan row close failed")
+			}
+			conflictErr := errors.New(errors.CodeConflict, "user with email already exist")
+			rollback(ctx, tx, conflictErr, "failed rollback after same-site email conflict")
+			return nil, conflictErr
+		}
+
+		userIDRaw = idData
+
+		if userJsonDataRaw != nil && len(userJsonData) == 0 {
+			if err := json.Unmarshal([]byte(*userJsonDataRaw), &userJsonData); err != nil {
+				_ = rows.Close()
+				rollback(ctx, tx, err, "failed rollback after unmarshal user jsondata failed")
+				return nil, errors.Wrap(err, errors.CodeInternalServerError, "Can not unmarshal user jsondata for create")
+			}
+		}
+
+		if scimExternalID, ok := userJsonData[jsondataSCIMExternalID]; ok && scimExternalID != user.GetSCIMExternalID() {
+			rollback(ctx, tx, err, "failed rollback after checking SCIM external ID")
+			return nil, errors.New(errors.CodeInvalidInput, "User already exists with another SCIM externalID")
+		}
+	}
+
+	var userGUID guid.GUID
+	if len(userIDRaw) == 0 {
+		userGUID = guid.New()
+		userIDRaw, err = userGUID.MarshalBinary()
+		if err != nil {
+			rollback(ctx, tx, err, "failed rollback after MarshalBinary on new user GUID")
+			return nil, errors.Wrap(err, errors.CodeInternalServerError,
+				"could not create raw user.ID")
+		}
+	} else {
+		userGUID, err = guid.FromBytes(userIDRaw)
+		if err != nil {
+			rollback(ctx, tx, err, "failed rollback after invalid existing user ID")
+			return nil, errors.Wrapf(err, errors.CodeInternalServerError,
+				"invalid format on user ID %x", userIDRaw)
+		}
+	}
+	user.ID = userGUID.String()
+
+	userJsonData[jsondataSCIMExternalID] = user.SCIMExternalID
+	jsonDataRawNew, err := json.Marshal(userJsonData)
+	if err != nil {
+		rollback(ctx, tx, err, "failed rollback after marshal of user jsondata failed")
+		return nil, errors.Wrap(err, errors.CodeInternalServerError, "Failed to marshal user jsondata")
+	}
+
+	if !emailExist {
+		userQuery := `
+		INSERT INTO sd_admin_users (
+			userid, email, username, namefirst, namelast, datecreated, datemodified, passwordhash, mfasecret, externalid, jsondata,
+			password, personalid, company, department, companyid, pin, openid,
+			customernumber, invoicedays, isadmin, timezone
+		)
+		VALUES (
+			?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
+			'', '', '', '', '', null, null, null, null, 0, null
+		);`
+		_, err = tx.ExecContext(ctx, userQuery, userIDRaw, user.GetEmail(), user.GetUserName(),
+			user.GetNameFirst(), user.GetNameLast(), dateTimeNow, dateTimeNow,
+			user.PasswordHash, user.MFASecret, user.ExternalID, string(jsonDataRawNew))
+		if err != nil {
+			rollback(ctx, tx, err, "failed rollback after failed userQuery")
+			return nil, err
+		}
+	}
+
+	if len(privs) > 0 {
+		// insert all privileges for userID on site
+		privQuery := `
+			INSERT INTO sd_admin_users_privs (userid, privid, siteid)
+			VALUES
+		`
+		var args []any
+		for i := range privs {
+			privQuery += "(?, ?, ?)"
+			if i == len(privs)-1 {
+				// last
+				privQuery += ";"
+			} else {
+				privQuery += ","
+			}
+			args = append(args, userIDRaw, privs[i], siteIDData)
+		}
+
+		_, err = tx.ExecContext(ctx, privQuery, args...)
+		if err != nil {
+			rollback(ctx, tx, err, "failed rollback from failed privQuery")
+			return nil, errors.Wrap(err, errors.CodeInternalServerError,
+				"error creating user in mysql")
+		}
+	}
+
+	if err = updatePosTokens(ctx, tx); err != nil {
+		rollback(ctx, tx, err, "failed rollback from failed token upsert")
+		return nil, err
+	}
+
+	if err := tx.Commit(); err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError,
+			"failed to commit create user transaction")
+	}
+
+	// SkipRolePrivs leaves no priv anchor at this site, so GetUserByID
+	// (which JOINs on sd_admin_users_privs) would 404. Return the
+	// just-constructed user — its ID and profile fields are authoritative
+	// for the IAM-bucket caller, which echoes role+stores from IAM.
+	return user, nil
+}
