+func GetUserProfilesInAccount(
+	c context.Context,
+	db *sql.DB,
+	start int64,
+	num int64,
+	filter map[string]string,
+) (*model.UsersEnvelope, error) {
+	ctx, cancelFn := context.WithTimeout(c, 10*time.Second)
+	defer cancelFn()
+
+	filterQuery := map[string]any{}
+	for k, v := range filter {
+		var val any = v
+		if k == "userID" {
+			id, err := guid.Parse(v)
+			if err != nil {
+				return nil, errors.WithMessage(err, "failed to extract userID value")
+			}
+			val, _ = id.MarshalBinary()
+		}
+
+		if translatedKey, ok := filterKeyTranslations[k]; ok {
+			filterQuery[translatedKey] = val
+			continue
+		}
+
+		log.MustGetFromContext(c).LogWarn(
+			log.Entry("got unexpected filter key (ignored)").
+				String("filter_key", k),
+		)
+		return nil, errors.Errorf(errors.CodeInvalidInput, "unsupported filter key '%s'", k)
+	}
+
+	// Sort keys so the WHERE clause is deterministic regardless of map
+	// iteration order. RDS Performance Insights groups by the literal
+	// query text — non-deterministic clauses produce phantom variants.
+	sortedKeys := make([]string, 0, len(filterQuery))
+	for k := range filterQuery {
+		sortedKeys = append(sortedKeys, k)
+	}
+	sort.Strings(sortedKeys)
+
+	sqlFilterValues := make([]any, 0, len(filterQuery))
+	whereStmt := "WHERE 1=1"
+	for _, k := range sortedKeys {
+		whereStmt += fmt.Sprintf(" AND %s=?", k)
+		sqlFilterValues = append(sqlFilterValues, filterQuery[k])
+	}
+
+	//nolint:gosec
+	usersQuery := `
+		SELECT U.userid, U.username, U.email, U.externalid, U.namefirst, U.namelast, U.jsondata
+		FROM sd_admin_users U
+		` + whereStmt + `
+		ORDER BY U.userid
+		LIMIT ? OFFSET ?;
+	`
+	usersQueryArgs := append(append([]any(nil), sqlFilterValues...), num, start)
+	usersRes, err := db.QueryContext(ctx, usersQuery, usersQueryArgs...)
+	if err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError,
+			"failed to query for users in mysql")
+	}
+	defer func() { _ = usersRes.Close() }()
+
+	//nolint:gosec
+	totalCountQuery := `
+		SELECT COUNT(*) FROM sd_admin_users U
+		` + whereStmt
+	totalCountRow := db.QueryRowContext(ctx, totalCountQuery, sqlFilterValues...)
+	var totalCount int64
+	if err := totalCountRow.Scan(&totalCount); err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError, "could not get total count")
+	}
+
+	users := make([]model.User, 0, num)
+	for usersRes.Next() {
+		var uRow userRow
+		if err := usersRes.Scan(
+			&uRow.id, &uRow.userName, &uRow.email, &uRow.externalID,
+			&uRow.nameFirst, &uRow.nameLast, &uRow.jsonData,
+		); err != nil {
+			return nil, errors.Wrap(err, errors.CodeInternalServerError,
+				"failed to scan users result")
+		}
+
+		id, err := guid.FromBytes(uRow.id)
+		if err != nil {
+			return nil, errors.Wrap(err, errors.CodeInternalServerError,
+				"failed to convert user id")
+		}
+
+		user := model.User{
+			Active:     new(true),
+			UserName:   uRow.userName,
+			Email:      uRow.email,
+			ExternalID: uRow.externalID,
+			NameFirst:  uRow.nameFirst,
+			NameLast:   uRow.nameLast,
+		}
+		user.ID = id.String()
+
+		jsonData := []byte(ptrtype.GetString(uRow.jsonData))
+		if len(jsonData) > 0 {
+			var m map[string]any
+			if err := json.Unmarshal(jsonData, &m); err == nil {
+				if v, ok := m[jsondataSCIMExternalID]; ok {
+					if vStr, isString := v.(string); isString {
+						user.SCIMExternalID = &vStr
+					}
+				}
+			}
+		}
+
+		users = append(users, user)
+	}
+	if err := usersRes.Err(); err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError, "error iterating users result")
+	}
+
+	return &model.UsersEnvelope{
+		TotalResults: totalCount,
+		Items:        users,
+	}, nil
+}
