+func GetUserProfileByID(
+	c context.Context,
+	db *sql.DB,
+	userID string,
+) (*model.User, error) {
+	idData, err := guid.Parse(userID)
+	if err != nil {
+		return nil, errors.Wrap(err, errors.CodeInvalidInput, "could not parse user id")
+	}
+	idDataRaw, err := idData.MarshalBinary()
+	if err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError, "could not marshal user id")
+	}
+
+	ctx, cancelFn := context.WithTimeout(c, 10*time.Second)
+	defer cancelFn()
+
+	query := `
+		SELECT username, email, externalid, namefirst, namelast, jsondata
+		FROM sd_admin_users
+		WHERE userid = ?
+		LIMIT 1;
+	`
+	row := db.QueryRowContext(ctx, query, idDataRaw)
+
+	var uRow userRow
+	if err = row.Scan(
+		&uRow.userName, &uRow.email, &uRow.externalID, &uRow.nameFirst, &uRow.nameLast,
+		&uRow.jsonData,
+	); err != nil {
+		if err == sql.ErrNoRows {
+			return nil, errors.New(errors.CodeNotFound, "no user found")
+		}
+		return nil, errors.Wrap(err, errors.CodeInternalServerError, "failed to query user profile")
+	}
+
+	// Build a minimal user: profile fields only. Active defaults to true;
+	// role + stores + POS are left at zero values for the caller to overlay.
+	user := model.User{
+		Active: ptrtype.NewBool(true),
+	}
+	id, err := guid.FromBytes(idDataRaw)
+	if err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError, "could not convert user id")
+	}
+	user.ID = id.String()
+	user.UserName = uRow.userName
+	user.Email = uRow.email
+	user.ExternalID = uRow.externalID
+	user.NameFirst = uRow.nameFirst
+	user.NameLast = uRow.nameLast
+
+	// Extract SCIM external ID from jsondata.
+	jsonData := []byte(ptrtype.GetString(uRow.jsonData))
+	if len(jsonData) > 0 {
+		var m map[string]any
+		if err := json.Unmarshal(jsonData, &m); err == nil {
+			if v, ok := m[jsondataSCIMExternalID]; ok {
+				if vStr, isString := v.(string); isString {
+					user.SCIMExternalID = &vStr
+				}
+			}
+		}
+	}
+
+	return &user, nil
+}
