+// UpdateUserProfile updates the user's profile fields in sd_admin_users
+// without requiring a sd_admin_users_privs row at any site. Used by SCIM
+// UpdateUser for IAM-bucket users that have no priv anchor in MySQL.
+// Returns the post-update profile (role/stores/POS zeroed; callers must
+// overlay from IAM).
+//
+// Supported fields (map keys, matching mysql.UpdateUser): email, userName,
+// nameFirst, nameLast, externalID, scimexternalid. Unknown keys are
+// ignored. Returns CodeNotFound when the user row is absent.
+func UpdateUserProfile(
+	c context.Context,
+	db *sql.DB,
+	userID string,
+	fields map[string]any,
+) (*model.User, error) {
+	idData, err := guid.Parse(userID)
+	if err != nil {
+		return nil, errors.Wrap(err, errors.CodeInvalidInput, "could not parse user id")
+	}
+	idDataRaw, err := idData.MarshalBinary()
+	if err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError, "could not marshal user id")
+	}
+
+	ctx, cancelFn := context.WithTimeout(c, 10*time.Second)
+	defer cancelFn()
+
+	// Build SET clause from the patch fields.
+	type pair struct {
+		col string
+		val any
+	}
+	colMap := map[string]string{
+		"email":      "email",
+		"userName":   "username",
+		"nameFirst":  "namefirst",
+		"nameLast":   "namelast",
+		"externalID": "externalid",
+	}
+	var pairs []pair
+	for k, col := range colMap {
+		if v, ok := fields[k]; ok {
+			pairs = append(pairs, pair{col, v})
+		}
+	}
+
+	// scimexternalid lives inside the jsondata blob — handled separately below if present.
+	scimExtIDPatch, hasSCIMExt := fields["scimexternalid"]
+
+	if len(pairs) == 0 && !hasSCIMExt {
+		// nothing to update — just read and return.
+		return GetUserProfileByID(c, db, userID)
+	}
+
+	tx, err := db.BeginTx(ctx, nil)
+	if err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError, "could not begin tx")
+	}
+
+	if hasSCIMExt {
+		// Read current jsondata, merge, write back.
+		var jsonBlob *string
+		err := tx.QueryRowContext(ctx,
+			"SELECT jsondata FROM sd_admin_users WHERE userid = ? LIMIT 1 FOR UPDATE", idDataRaw,
+		).Scan(&jsonBlob)
+		if err != nil {
+			rollback(ctx, tx, err, "read jsondata for profile update")
+			if err == sql.ErrNoRows {
+				return nil, errors.New(errors.CodeNotFound, "no user found")
+			}
+			return nil, errors.Wrap(err, errors.CodeInternalServerError, "read jsondata")
+		}
+		m := map[string]any{}
+		if jsonBlob != nil && *jsonBlob != "" {
+			if err := json.Unmarshal([]byte(*jsonBlob), &m); err != nil {
+				rollback(ctx, tx, err, "unmarshal jsondata for profile update")
+				return nil, errors.Wrap(err, errors.CodeInternalServerError, "unmarshal jsondata")
+			}
+		}
+		if v, ok := scimExtIDPatch.(*string); ok && v != nil {
+			m[jsondataSCIMExternalID] = *v
+		}
+		merged, mErr := json.Marshal(m)
+		if mErr != nil {
+			rollback(ctx, tx, mErr, "marshal merged jsondata")
+			return nil, errors.Wrap(mErr, errors.CodeInternalServerError, "marshal jsondata")
+		}
+		pairs = append(pairs, pair{"jsondata", string(merged)})
+	}
+
+	if len(pairs) > 0 {
+		setClauses := make([]string, 0, len(pairs)+1)
+		args := make([]any, 0, len(pairs)+2)
+		for _, p := range pairs {
+			setClauses = append(setClauses, p.col+" = ?")
+			// dereference *string if needed
+			switch v := p.val.(type) {
+			case *string:
+				if v == nil {
+					args = append(args, nil)
+				} else {
+					args = append(args, *v)
+				}
+			default:
+				args = append(args, v)
+			}
+		}
+		setClauses = append(setClauses, "datemodified = ?")
+		args = append(args, timeNow().UTC().Format(dateTimeFmt))
+		args = append(args, idDataRaw)
+		//nolint:gosec // setClauses keys built from colMap whitelist
+		query := "UPDATE sd_admin_users SET " + strings.Join(setClauses, ", ") + " WHERE userid = ?"
+		res, err := tx.ExecContext(ctx, query, args...)
+		if err != nil {
+			rollback(ctx, tx, err, "update sd_admin_users profile")
+			return nil, errors.Wrap(err, errors.CodeInternalServerError, "update profile")
+		}
+		affected, _ := res.RowsAffected()
+		if affected == 0 {
+			_ = tx.Rollback()
+			return nil, errors.New(errors.CodeNotFound, "no user found")
+		}
+	}
+
+	if err := tx.Commit(); err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError, "commit profile update")
+	}
+
+	return GetUserProfileByID(c, db, userID)
+}
+
+func DeleteUserPrivsAtSite(
+	c context.Context,
+	db *sql.DB,
+	siteID int64,
+	userID string,
+) (int, error) {
+	idData, err := guid.Parse(userID)
+	if err != nil {
+		return 0, errors.New(errors.CodeInvalidInput, "could not parse id data")
+	}
+	idDataRaw, err := idData.MarshalBinary()
+	if err != nil {
+		return 0, errors.Wrap(err, errors.CodeInternalServerError, "could not marshal user id")
+	}
+
+	siteIDData, err := getSiteIDData(c, db, siteID)
+	if err != nil {
+		return 0, errors.WithMessage(err, "delete user privs at site")
+	}
+
+	ctx, cancelFn := context.WithTimeout(c, 10*time.Second)
+	defer cancelFn()
+
+	tx, err := db.BeginTx(ctx, nil)
+	if err != nil {
+		return 0, errors.Wrap(err, errors.CodeInternalServerError,
+			"could not create mysql transaction")
+	}
+
+	deletePrivs := `
+		DELETE FROM sd_admin_users_privs
+		WHERE userid = ? AND siteid = ?
+	`
+	res, err := tx.ExecContext(ctx, deletePrivs, idDataRaw, siteIDData)
+	if err != nil {
+		rollback(ctx, tx, err, "failed rollback after deleting site privs")
+		return 0, errors.Wrap(err, errors.CodeInternalServerError,
+			"failed to delete site privs")
+	}
+	numPrivsRemoved, _ := res.RowsAffected()
+
+	queryPrivs := `SELECT COUNT(*) FROM sd_admin_users_privs WHERE userid = ?`
+	row := tx.QueryRowContext(ctx, queryPrivs, idDataRaw)
+	var remaining int
+	if err := row.Scan(&remaining); err != nil {
+		rollback(ctx, tx, err, "failed rollback after counting remaining privs")
+		return 0, errors.Wrap(err, errors.CodeInternalServerError,
+			"failed to count remaining privs")
+	}
+
+	if err := tx.Commit(); err != nil {
+		return 0, errors.Wrap(err, errors.CodeInternalServerError,
+			"failed to commit DeleteUserPrivsAtSite transaction")
+	}
+
+	if numPrivsRemoved == 0 {
+		return remaining, errors.New(errors.CodeNotFound,
+			"no priv rows at site for user")
+	}
+	return remaining, nil
+}
+
+// UserPrivState carries the per-(site, user) priv-derived flags that
+// SCIM responses must reflect from the legacy DB regardless of role
+// bucket (legacy vs IAM).
+type UserPrivState struct {
+	Active        bool
+	PosRefundCard bool
+	PosAllStores  bool
+}
+
+// GetUserByIDV2 returns the user with profile + priv-derived Active/POS
+// flags + warehouse-mirrored stores at (siteID, userID), in a single
+// query. Unlike legacy getUserRow it does NOT require a priv anchor at
+// the site — IAM-bucket users with zero priv rows still resolve, with
+// Active=true and POS flags = false (presence/absence of priv rows IS
+// the derivation). 404 only when the user row itself is missing.
+//
+// Role bools on the returned *model.User are left at their zero values;
+// V2 callers must overlay role + stores from IAM via
+// overrideRoleStoresFromIAM. Stores are populated from the warehouse
+// JOIN (legacy mirror) and may be overwritten by IAM downstream.
+func GetUserByIDV2(
+	c context.Context,
+	db *sql.DB,
+	siteID int64,
+	userID string,
+) (*model.User, error) {
+	idData, err := guid.Parse(userID)
+	if err != nil {
+		return nil, errors.Wrap(err, errors.CodeInvalidInput, "could not parse user id")
+	}
+	idDataRaw, err := idData.MarshalBinary()
+	if err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError, "could not marshal user id")
+	}
+
+	siteIDData, err := getSiteIDData(c, db, siteID)
+	if err != nil {
+		return nil, err
+	}
+
+	ctx, cancelFn := context.WithTimeout(c, 10*time.Second)
+	defer cancelFn()
+
+	// FROM sd_admin_users U so we always get a row when the user exists,
+	// even when there are no priv rows at the requested site. Priv-site
+	// predicate moves into the LEFT JOIN clause so non-matching priv
+	// rows at OTHER sites don't leak into this read.
+	query := `
+		SELECT U.username, U.email, U.externalid, U.namefirst, U.namelast, U.jsondata,
+			   GROUP_CONCAT(P.privid), GROUP_CONCAT(S.externalid)
+		FROM sd_admin_users U
+		LEFT JOIN sd_admin_users_privs P ON U.userid = P.userid AND P.siteid = ?
+		LEFT JOIN sd_warehouses W ON (P.privid >= 10000 AND (P.privid - 10000) = W.warehouseid)
+		LEFT JOIN sd_stores S ON W.storeid = S.storeid
+		WHERE U.userid = ?
+		GROUP BY U.userid
+		LIMIT 1;
+	`
+	row := db.QueryRowContext(ctx, query, siteIDData, idDataRaw)
+
+	var uRow userRow
+	if err = row.Scan(
+		&uRow.userName, &uRow.email, &uRow.externalID, &uRow.nameFirst, &uRow.nameLast,
+		&uRow.jsonData, &uRow.privsStr, &uRow.storesStr,
+	); err != nil {
+		if err == sql.ErrNoRows {
+			return nil, errors.New(errors.CodeNotFound, "no user found")
+		}
+		return nil, errors.Wrap(err, errors.CodeInternalServerError,
+			"failed to query for user in mysql")
+	}
+	uRow.id = idDataRaw
+
+	return uRow.toUserV2()
+}
+
+// toUserV2 converts a userRow into a *model.User for the V2 SCIM read
+// path. Differs from userRow.toUser() in two ways:
+//   - tolerates NULL/empty privsStr (no priv rows at site) — defaults
+//     Active=true, POS bools=false. legacy toUser() crashes here because
+//     legacy getUserRow only ever returns rows with at least one priv.
+//   - skips role priv → bool mapping; V2 callers overlay role from IAM.
+func (u userRow) toUserV2() (*model.User, error) {
+	user := &model.User{
+		UserName:      u.userName,
+		Email:         u.email,
+		ExternalID:    u.externalID,
+		NameFirst:     u.nameFirst,
+		NameLast:      u.nameLast,
+		PosRefundCard: ptrtype.NewBool(false),
+		PosAllStores:  ptrtype.NewBool(false),
+		Active:        ptrtype.NewBool(true),
+	}
+
+	id, err := guid.FromBytes(u.id)
+	if err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError, "could not convert user id")
+	}
+	user.ID = id.String()
+
+	// SCIM external id from jsondata.
+	jsonData := []byte(ptrtype.GetString(u.jsonData))
+	if len(jsonData) > 0 {
+		var m map[string]any
+		if err := json.Unmarshal(jsonData, &m); err == nil {
+			if v, ok := m[jsondataSCIMExternalID]; ok {
+				if vStr, isString := v.(string); isString {
+					user.SCIMExternalID = &vStr
+				}
+			}
+		}
+	}
+
+	// Priv-derived flags. Empty privsStr → leave defaults.
+	if s := ptrtype.GetString(u.privsStr); s != "" {
+		for _, p := range strings.Split(s, ",") {
+			v, err := strconv.Atoi(p)
+			if err != nil {
+				return nil, errors.Wrapf(err, errors.CodeInternalServerError,
+					"failed to convert priv %q to int", p)
+			}
+			switch v {
+			case userPrivNotActive:
+				user.Active = ptrtype.NewBool(false)
+			case userPrivPosRefundCard:
+				user.PosRefundCard = ptrtype.NewBool(true)
+			case userPrivPosAllStores:
+				user.PosAllStores = ptrtype.NewBool(true)
+			}
+		}
+	}
+
+	// Stores mirrored from legacy warehouse JOIN (may be overridden by IAM).
+	stores := []string{}
+	if u.storesStr != nil {
+		stores = filterStrDuplicates(strings.Split(*u.storesStr, ","))
+	}
+	user.Stores = stores
+
+	return user, nil
+}
+
+// GetUserPrivStatesAtSite is the batch variant for listing endpoints.
+// Returns a map keyed by user ID (canonical guid.String() — braces form,
+// matching what getUserRow / GetUserProfileByID produce for user.ID).
+// Users with no priv rows at the site are ABSENT from the map; callers
+// MUST treat absent as zero state with Active=true (the map's zero value
+// has Active=false which is the wrong default).
+//
+// Empty userIDs → empty map, no DB call.
+func GetUserPrivStatesAtSite(
+	c context.Context,
+	db *sql.DB,
+	siteID int64,
+	userIDs []string,
+) (map[string]UserPrivState, error) {
+	out := make(map[string]UserPrivState, len(userIDs))
+	if len(userIDs) == 0 {
+		return out, nil
+	}
+
+	// Bulk-marshal user IDs; reject the whole batch on a bad input so the
+	// caller does not silently get partial results.
+	rawIDs := make([][]byte, 0, len(userIDs))
+	for _, id := range userIDs {
+		g, err := guid.Parse(id)
+		if err != nil {
+			return nil, errors.Wrapf(err, errors.CodeInvalidInput,
+				"could not parse user id %q", id)
+		}
+		raw, err := g.MarshalBinary()
+		if err != nil {
+			return nil, errors.Wrap(err, errors.CodeInternalServerError,
+				"could not marshal user id")
+		}
+		rawIDs = append(rawIDs, raw)
+	}
+
+	siteIDData, err := getSiteIDData(c, db, siteID)
+	if err != nil {
+		return nil, err
+	}
+
+	ctx, cancelFn := context.WithTimeout(c, 10*time.Second)
+	defer cancelFn()
+
+	placeholders := strings.Repeat("?,", len(rawIDs))
+	placeholders = placeholders[:len(placeholders)-1]
+	args := make([]any, 0, len(rawIDs)+1)
+	args = append(args, siteIDData)
+	for _, raw := range rawIDs {
+		args = append(args, raw)
+	}
+	//nolint:gosec // placeholders are fixed-count ? markers only
+	query := `SELECT userid, privid FROM sd_admin_users_privs WHERE siteid = ? AND userid IN (` + placeholders + `)`
+
+	rows, err := db.QueryContext(ctx, query, args...)
+	if err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError,
+			"failed to query user priv states")
+	}
+	defer func() { _ = rows.Close() }()
+
+	for rows.Next() {
+		var raw []byte
+		var p int
+		if err := rows.Scan(&raw, &p); err != nil {
+			return nil, errors.Wrap(err, errors.CodeInternalServerError,
+				"failed to scan user priv row")
+		}
+		g, err := guid.FromBytes(raw)
+		if err != nil {
+			return nil, errors.Wrap(err, errors.CodeInternalServerError,
+				"failed to convert user id")
+		}
+		key := g.String()
+		state, ok := out[key]
+		if !ok {
+			state = UserPrivState{Active: true}
+		}
+		switch p {
+		case userPrivNotActive:
+			state.Active = false
+		case userPrivPosRefundCard:
+			state.PosRefundCard = true
+		case userPrivPosAllStores:
+			state.PosAllStores = true
+		}
+		out[key] = state
+	}
+	if err := rows.Err(); err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError,
+			"error iterating user priv rows")
+	}
+	return out, nil
+}
+
+// DeleteUserRow deletes the sd_admin_users row unconditionally for a given
+// user id. Called by the SCIM DeleteUser path after the IAM site delete and
+// account-presence check confirm the user has no remaining presence in MySQL
+// or IAM. Caller is responsible for removing any priv rows that should not
+// outlive the user.
+func DeleteUserRow(c context.Context, db *sql.DB, userID string) error {
+	idData, err := guid.Parse(userID)
+	if err != nil {
+		return errors.New(errors.CodeInvalidInput, "could not parse id data")
+	}
+	idDataRaw, err := idData.MarshalBinary()
+	if err != nil {
+		return errors.Wrap(err, errors.CodeInternalServerError, "could not marshal user id")
+	}
+
+	ctx, cancelFn := context.WithTimeout(c, 10*time.Second)
+	defer cancelFn()
+
+	tx, err := db.BeginTx(ctx, nil)
+	if err != nil {
+		return errors.Wrap(err, errors.CodeInternalServerError, "could not begin tx")
+	}
+	if _, err := tx.ExecContext(ctx, `DELETE FROM sd_admin_users_privs WHERE userid = ?`, idDataRaw); err != nil {
+		rollback(ctx, tx, err, "failed rollback after clear privs before user delete")
+		return errors.Wrap(err, errors.CodeInternalServerError, "failed to clear privs before user delete")
+	}
+	if _, err := tx.ExecContext(ctx, `DELETE FROM sd_admin_users WHERE userid = ?`, idDataRaw); err != nil {
+		rollback(ctx, tx, err, "failed rollback after delete user row")
+		return errors.Wrap(err, errors.CodeInternalServerError, "failed to delete user row")
+	}
+	if err := tx.Commit(); err != nil {
+		return errors.Wrap(err, errors.CodeInternalServerError, "failed to commit DeleteUserRow transaction")
+	}
+	return nil
+}

