+package service
+
+import (
+	"context"
+	"os"
+	"testing"
+
+	"github.com/google/uuid"
+	"github.com/sitoo/auth/app"
+	genmodel "github.com/sitoo/auth/generated/model"
+	"github.com/sitoo/auth/model"
+	"github.com/sitoo/auth/provider/iam"
+	"github.com/sitoo/go-utils-common/errors"
+	"github.com/sitoo/go-utils-common/log"
+	"github.com/sitoo/go-utils-common/ptrtype"
+	"github.com/sitoo/go-utils-common/system"
+	sysmodel "github.com/sitoo/go-utils-common/system/model"
+	"github.com/stretchr/testify/require"
+)
+
+func TestMain(m *testing.M) {
+	_ = log.InitLogger(log.Config{
+		ServiceName: "auth",
+		Version:     app.Version,
+		LogLevel:    log.DebugLevel,
+	})
+	os.Exit(m.Run())
+}
+
+func TestStoresStringToIDs(t *testing.T) {
+	cases := []struct {
+		in   string
+		want []int64
+		err  bool
+	}{
+		{"", nil, false},
+		{"1", []int64{1}, false},
+		{"1,2,3", []int64{1, 2, 3}, false},
+		{"  4 , 5 ", []int64{4, 5}, false},
+		{"abc", nil, true},
+		{"1,abc", nil, true},
